"""Deterministic self-contained analyst applications and static executive reports."""
import csv,json,html
from config import ROOT,LAND,HOTEL
CSS='''*{box-sizing:border-box}body{margin:0;background:#f3f1eb;color:#182c38;font:16px/1.55 system-ui,sans-serif}header{background:#102e37;color:white;padding:35px max(20px,calc((100vw - 1160px)/2))}header p{color:#bdced0;max-width:850px}h1{font-size:clamp(28px,4vw,43px);line-height:1.15;max-width:1000px;margin:12px 0}h2{font-size:23px;line-height:1.3}h3{font-size:18px}.eyebrow{text-transform:uppercase;letter-spacing:.14em;font-size:12px;color:#99e1d4}main{max-width:1200px;margin:0 auto;padding:25px 20px 50px}section,.panel{background:#fff;padding:24px;border:1px solid #d7dedc;border-radius:12px;margin-bottom:22px;min-width:0}a{color:#14655c}header a{color:#c1eee3}button{background:#17675f;color:white;padding:11px 18px;border:0;border-radius:6px;font:inherit;cursor:pointer}button.secondary{background:#e8efed;color:#173c39}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #d47d28;outline-offset:3px}.controls{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.control{min-width:0;max-width:100%}label{display:block;font-size:13px;font-weight:650;margin-bottom:5px}.bounded{width:100%;min-width:0;max-width:100%;contain:inline-size}select,input{display:block;width:100%;max-width:100%;min-width:0;padding:10px;border:1px solid #a9bdb8;border-radius:5px;font:inherit;background:white;color:#18352d}form .actions{margin-top:20px;display:flex;gap:10px;flex-wrap:wrap}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin:22px 0}.metric{border-left:4px solid #d18542;background:#f3f7f5;padding:17px;min-width:0}.metric strong{font-size:clamp(22px,2.4vw,33px);display:block;overflow-wrap:anywhere;line-height:1.25}.metric small{color:#516762}.notice{padding:15px 18px;border-left:4px solid #d18542;background:#fff4e8;margin:18px 0}#error{color:#a12727;font-weight:650;min-height:26px}#decision{font-weight:700;color:#14655c}.table-scroll{width:100%;max-width:100%;overflow:auto;max-height:600px;min-width:0}table{border-collapse:collapse;min-width:700px;width:100%;font-size:13px}th,td{text-align:left;padding:11px 12px;border-bottom:1px solid #e1e7e3;white-space:nowrap}th{background:#eaf1ef}#count{font-size:13px;color:#52675d}.intro{max-width:900px}.chart{max-width:100%;height:auto;display:block}.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.subtle{color:#52675d;font-size:14px}.legend{font-size:13px;color:#52675d}.badge{font-size:12px;color:#724009;background:#ffeedb;padding:4px 9px;border-radius:20px;display:inline-block}footer{font-size:13px;padding-top:20px;color:#52675d}@media(max-width:900px){.controls{grid-template-columns:repeat(2,minmax(0,1fr))}.metrics{grid-template-columns:1fr 1fr}.two{grid-template-columns:1fr}}@media(max-width:550px){header{padding:25px 18px}main{padding:18px 12px}section,.panel{padding:17px}.controls,.metrics{grid-template-columns:minmax(0,1fr)}.metric strong{font-size:28px}}'''
def rows(p,n):
 with (ROOT/p/'outputs'/n).open() as f:return list(csv.DictReader(f))
def money(v):return f'${v/1e9:,.3f}B'
def table(rs,cols):
 return '<div class="table-scroll" tabindex="0" aria-label="Scrollable evidence table"><table><thead><tr>'+''.join('<th>'+html.escape(c.replace('_',' ').title())+'</th>' for c in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(money(r[c]) if isinstance(r.get(c),float) else str(r.get(c,'')))+'</td>' for c in cols)+'</tr>' for r in rs)+'</tbody></table></div>'
def chart(latest,land):
 # Two observed measures on the same dollar scale; no modeled savings are shown.
 a='disclosed_at_risk_cost' if land else 'revenue';b='remaining_price' if land else 'reimb_revenue';mx=max(float(r[x]) for r in latest for x in [a,b]);svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 310" role="img" aria-label="Observed issuer financial comparison"><rect width="600" height="310" fill="#fff"/>']
 for i,r in enumerate(latest):
  y=40+i*90;svg.append(f'<text x="10" y="{y+20}" font-family="sans-serif" font-size="20" fill="#173b39">{r["ticker"]}</text>')
  for j,(x,color) in enumerate([(a,'#187567'),(b,'#cc7d3d')]):
   v=float(r[x]);w=320*v/mx;yy=y+j*28;svg.append(f'<rect x="75" y="{yy}" width="{w:.3f}" height="20" rx="3" fill="{color}"/><text x="{85+w:.3f}" y="{yy+16}" font-family="sans-serif" font-size="20" fill="#173b39">{money(v)}</text>')
 svg.append('</svg>');return ''.join(svg)
def run(project):
 root=ROOT/project;out=root/'outputs';land=project==LAND;m=json.loads((out/'metrics.json').read_text());history=rows(project,'panel.csv');latest=rows(project,'latest_decisions.csv');lineage=rows(project,'source_lineage.csv')
 for r in history+latest:
  for k,v in list(r.items()):
   if k not in ['ticker','scope','end','start','period','filed','accession','price_basis','exposure_basis','extra_cost_scope','action','gate']:
    try:r[k]=float(v)
    except(ValueError,TypeError):pass
 for r in latest:r['source_url']=next(x['source_url'] for x in lineage if x['ticker']==r['ticker'] and x['accession']==r['accession'])
 title='Homebuilder Land Option Diligence' if land else 'Hotel Reimbursement Economics'
 question='When is walking away from a land contract rational despite a sunk deposit?' if land else 'How much apparent margin change comes from reimbursement accounting?'
 finding=f"{m['records']} contract-scope/date records reconcile {money(m['current_disclosed_cost'])} of mixed-basis disclosed capital at risk and {money(m['current_remaining_purchase_price'])} of conditional remaining purchase prices." if land else f"Across three operators, H1 2026 cost-recovery revenue is {money(m['h1_2026_reimbursement_revenue'])} of {money(m['h1_2026_revenue'])} reported revenue; the net reimbursement balance is {money(m['h1_2026_recovery_balance'])}."
 conclusion='Use the contract register to separate funded exposure from optional future outlays. Request tract-level values, refund rights and minimum-take schedules before authorizing exercise or extensions.' if land else 'Use the exact income bridge before authorizing program spending. Obtain contractual recoverability and a forward operating budget; neither reimbursement revenue nor normalized operating income is free cash.'
 legend='Green: disclosed at-risk cost (mixed definitions). Orange: conditional remaining purchase price (not debt).' if land else 'Green: reported H1 revenue. Orange: reimbursement revenue included in that revenue.'
 (out/'decision_evidence.svg').write_text(chart(latest,land))
 common=f'<header><div class="eyebrow">Prathamesh Singh · Independent finance research · 22 October 2026</div><h1>{title}</h1><p>{question}</p><a href="report.html">Executive report</a> · <a href="app.html">Analyst workbench</a></header><main>'
 brief=f'# Executive brief\n\n{question}\n\n{finding}\n\n{conclusion}\n\n'
 brief+=('The 243 option scenarios and 27 refund sensitivities use assumed parcel values, probabilities, discounts, extension costs and refundability. They are not estimated option values. The empirical decision is to retain a contract register with reconciled boundaries and seek deal-level diligence, not to acquire or abandon the aggregate portfolios. PHM deposits include pre-acquisition costs, MTH reports cash deposits, and KBH separately reports pre-acquisition costs. Fiscal observation dates differ. Meritage\'s legacy committed subtotal includes balance-sheet contracts in 2021; summing the three off-balance-sheet committed categories resolves the scope difference. Its 2026 reused tag does not prove refundability.\n' if land else 'The 216 scenarios vary assumed reimbursement growth, cost growth, incremental program spend and a management income floor. They hold the non-reimbursement business fixed, so they are local budget sensitivities rather than earnings forecasts. Excluding net reimbursement balances does not remove owned-hotel activity, corporate costs, co-brand revenue or other GAAP items. All six within-issuer period-matched year-over-year income changes reconcile exactly to the core and reimbursement components. Historical comparative disclosures are selected as available at the cutoff, not recreated as originally known at each date.\n')
 brief+='\nInformation cutoff: filings through 21 October 2026; latest observations are explicitly dated. Public numerical facts and original source links are pinned. Adoption gate remains false because decision-critical contractual/forward inputs are absent. No causal claim or professional tenure is implied.\n'
 (out/'executive_brief.md').write_text(brief)
 cols=['ticker','end','deposits','remaining_price','disclosed_at_risk_cost'] if land else ['ticker','end','revenue','reimb_revenue','recovery_balance','profit_ex_recovery']
 report=common+f'<section><span class="badge">Research prototype · decision adoption withheld</span><h2>Decision in one minute</h2><p class="intro">{finding}</p><p class="intro">{conclusion}</p><img class="chart" src="decision_evidence.svg" alt="Observed issuer comparison"/><p class="legend">{legend}</p></section><section><h2>Observed evidence, before scenarios</h2>'+table(latest,cols)+'</section><section><h2>Where the conclusion stops</h2>'+''.join('<p>'+html.escape(p)+'</p>' for p in brief.split('\n\n')[4:])+'</section><section><h2>Audit trail</h2><p>Read panel.csv, source_lineage.csv, source_manifest.json, methodology and the excluded observations before applying a result. Main software checks and browser evidence are recorded separately from the failed real-world adoption gate.</p><p><a href="app.html">Open the local analyst workflow</a></p></section><footer>Local/offline application. Source publication does not host a live service.</footer></main>'
 (out/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+title+' · Executive report</title><style>'+CSS+'</style>'+report+'</html>')
 controls=[('value_ratio','Current net land value / remaining price',1.05,0,3),('up','One-year upside multiplier',1.25,1,2),('down','One-year downside multiplier',.75,0,1),('p','Assumed upside probability',.5,0,1),('rate','One-year discount rate',.1,0,.5),('extension','Extension cost / remaining price',.02,0,.5),('refund','Refund fraction of reported deposit',0,0,1)] if land else [('cost_growth','Reimbursement expense growth',0,-.5,.5),('recovery_growth','Reimbursement revenue growth',0,-.5,.5),('budget_share','New program spend / net revenue',0,0,.5),('target_margin','Income floor / net revenue',.15,0,1)]
 fields='<div class="control"><label for="issuer">Issuer</label><div class="bounded"><select id="issuer">'+''.join(f'<option value="{r["ticker"]}">{r["ticker"]} · {r["end"]}</option>' for r in latest)+'</select></div></div>'
 for id,label,default,lo,hi in controls:fields+=f'<div class="control"><label for="{id}">{label}</label><input id="{id}" type="number" step="any" value="{default}" min="{lo}" max="{hi}"></div>'
 columns=['ticker','end','scope','deposits','disclosed_price','remaining_price','price_basis','exposure_basis'] if land else ['ticker','start','end','period','revenue','reimb_revenue','reimb_expense','op_income']
 payload={'kind':'land' if land else 'hotel','latest':latest,'history':history,'columns':columns,'metrics':m}
 app=common+f'<section><span class="badge">Every control below is a scenario assumption</span><h2>Start with a source-backed issuer</h2><p>{finding}</p><div class="notice">'+('Deposits already paid are sunk unless refundable. Future land value is net of subsequent development costs. Extension rights, state probabilities and parcel values are unobserved. Aggregating contracts does not value individual exercise flexibility.' if land else 'This is an accrual income sensitivity. Hold the business excluding reimbursements fixed; change program cost, recovery and spend assumptions. Actual billability and cash collection dates are unknown.')+'</div><form id="form" novalidate><div class="controls">'+fields+'</div><div class="actions"><button type="submit">Calculate scenario</button><button type="button" class="secondary" id="reset">Reset</button></div></form><p id="error" role="alert"></p><div id="results" aria-live="polite"><p id="decision"></p><div class="metrics"><div class="metric"><small>'+('Wait minus best immediate payoff' if land else 'Scenario operating income')+'</small><strong id="result"></strong></div><div class="metric"><small>'+('Exercise indifference threshold' if land else 'Required recovery growth for floor')+'</small><strong id="threshold"></strong></div></div><p id="detail"></p><a id="source" target="_blank" rel="noopener">Original filing</a></div></section><section><h2>Inspect the observed history</h2><label for="search">Search issuer, date or scope</label><input type="search" id="search" placeholder="Try an issuer or 2025"/><p id="count" aria-live="polite"></p><div class="table-scroll" tabindex="0" aria-label="Scrollable source history"><table><thead><tr>'+''.join('<th>'+c.replace('_',' ').title()+'</th>' for c in columns)+'</tr></thead><tbody id="history-body"></tbody></table></div></section><footer>Observed values are separately labeled above. Scenarios do not authorize investments or represent forecasts. This self-contained application runs locally/offline.</footer></main>'
 script=(ROOT/'workbench.js').read_text();js=json.dumps(payload,separators=(',',':')).replace('</','<\\/')
 (out/'app.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+title+' · Analyst workbench</title><style>'+CSS+'</style>'+app+'<script type="application/json" id="dataset">'+js+'</script><script>'+script+'</script></html>')
if __name__=='__main__':
 for p in [LAND,HOTEL]:run(p)
